  ui_story_31780401_47_dialog_content = "Saya punya dua kelinci Peko di sini. Mereka ganas, dan mereka suka menggigit orang secara alami.",
  ui_story_31780401_48_dialog_content = "Seorang bangsawan Lumopolis membelinya dan memintaku untuk menjinakkannya.",
  ui_story_31780401_49_dialog_content = "Bagaimana dengan Anda dan saya masing-masing mengambil satu dan menggunakan metode masing-masing untuk melatih mereka selama sepuluh hari?",
  ui_story_31780401_50_dialog_content = "Setelah itu, mari kita lihat Peko siapa yang dalam kondisi terbaik dan memiliki temperamen paling ideal. Bagaimana menurutmu?",
