  ui_story_31780401_54_dialog_content = "Peko-peko!",
  ui_story_31780401_55_dialog_content = "Jenis kelamin, usia, dan kondisi fisik mereka saat ini sama. Saya akan membiarkan Anda memilih dulu.",
  ui_story_31780401_56_dialog_content = "Bagaimana? Ini akan menjadi kompetisi yang benar-benar adil.",
  ui_story_31780401_57_dialog_content = "<size=30>Seorang bangsawan Lumopolis...?</size>",
  ui_story_31780401_58_dialog_content = "Baik. Aku akan mengambil satu ini.",
  ui_story_31780401_59_dialog_content = "Oke, kita akan bertemu di sini saat ini 10 hari dari sekarang.",
  ui_story_31780401_60_dialog_content = "Nama saya Stiggan.",
  ui_story_31780401_61_dialog_content = "Oh, aku ingat sekarang!",
  ui_story_31780401_62_dialog_content = "Kurasa itu benar-benar terjadi...",
  ui_story_31780401_63_dialog_content = "Anda akhirnya ingat! Saya pikir kilas balik itu akan berlangsung selamanya!",
  ui_story_31780401_64_dialog_content = "Setelah kami kembali, saya mencari pria Stiggan itu.",
  ui_story_31780401_65_dialog_content = "Dia rupanya ahli ekstrozoologi terkenal.",
  ui_story_31780401_66_dialog_content = "Dia bahkan memberikan beberapa kuliah di Lumopolis!",
  ui_story_31780401_67_dialog_content = "Itu jelas bukan seseorang yang harus kamu anggap enteng... Apakah kamu benar-benar tidak khawatir?",
  ui_story_31780401_68_dialog_content = "Dia bahkan tidak bisa mengerti ketika Little Furball menyuruhnya pergi! Apa yang harus saya takuti?",
  ui_story_31780401_69_dialog_content = "Akan lebih masuk akal bagi Anda untuk bertanya kepada saya mengapa saya bahkan ingin berpartisipasi dalam kompetisi lelucon seperti itu.",
  ui_story_31780401_70_dialog_content = "Hah? Little Furball menyuruhnya pergi? Itu sebabnya kedengarannya sangat kacau!",
  ui_story_31780401_71_dialog_content = "Benar.",
  ui_story_31780401_72_dialog_content = "Apa yang dikatakannya?",
  ui_story_31780401_73_dialog_content = "\"Kamu tidak tahu apa-apa!\"",
  ui_story_31780401_74_dialog_content = "...",
  ui_story_31780401_75_dialog_content = "Bagaimanapun, kami telah menerima tantangannya, kami harus menepati janji kami!",
  ui_story_31780401_76_dialog_content = "Kita akan terlambat. Kembali ke kamarmu dan cuci mukamu... dan bawa Peko bersamamu!",
  ui_story_31780401_77_dialog_content = "Hei, jangan dorong aku!",
  ui_story_31780401_78_dialog_content = "Aduh, itu menyakitkan! Lenganku-",
  ui_story_31780401_79_dialog_content = "Kamu terlambat.",
  ui_story_31780401_80_dialog_content = "M-Maaf, sesuatu muncul.",
  ui_story_31780401_81_dialog_content = "<size=30>Vic, kamu harus minta maaf.</size>",
  ui_story_31780401_82_dialog_content = "* Menguap * Mari kita selesaikan ini, aku mengantuk.",
  ui_story_31780401_83_dialog_content = "...",
  ui_story_31780401_84_dialog_content = "...",
  ui_story_31780401_85_dialog_content = "Hanya dari mengamati sikapmu, aku sudah menyesal membuang waktuku yang berharga bersamamu.",
  ui_story_31780401_86_dialog_content = "Ayo cepat dan bandingkan Peko agar aku bisa mengembalikannya ke bangsawan itu.",
  ui_story_31780401_87_dialog_content = "peko...",
  ui_story_31780401_88_dialog_content = "Lihat ini. Peko ini tidak lagi menolak sentuhan Aurorian.",
  ui_story_31780401_89_dialog_content = "Di mana pun Anda menyentuhnya, Anda tidak perlu khawatir itu menggigit Anda.",
  ui_story_31780401_90_dialog_content = "Itu benar... tapi sepertinya dia kehilangan sedikit keberaniannya.",
  ui_story_31780401_91_dialog_content = "Lagipula sepuluh hari terlalu singkat, jadi sangat sulit untuk menjinakkannya.",
  ui_story_31780401_92_dialog_content = "Tidak mudah bagi saya untuk mencapai tingkat kepatuhan ini. Saya harus memanfaatkan sepenuhnya pemahaman saya tentang kebiasaan Kelinci Peko.",
  ui_story_31780401_93_dialog_content = "Tapi Peko lainnya hanya butuh dua hari untuk memulihkan vitalitasnya sepenuhnya!",
  ui_story_31780401_94_dialog_content = "Itu menjadi sangat ramah dan bermain dengan semua Aurorian di Colossus.",
  ui_story_31780401_95_dialog_content = "Berbicara itu murah. Mari kita lihat.",
  ui_story_31780401_96_dialog_content = "Jadi, anak muda, dimana Peko mu?",
  ui_story_31780401_97_dialog_content = "Saya melepaskannya.",
  ui_story_31780401_98_dialog_content = "Apa? Kau melepaskannya!?",
  ui_story_31780401_99_dialog_content = "Hah? Mengapa!? Jelas Anda akan memenangkan taruhan, Vic!",
  ui_story_31780401_100_dialog_content = "Saya tidak ingin berpartisipasi dalam hal ini sejak awal.",
  ui_story_31780401_101_dialog_content = "Apa gunanya memukul orang tua? Bahkan tidak ada uang yang dipertaruhkan.",
  ui_story_31780401_102_dialog_content = "...",
  ui_story_31780401_103_dialog_content = "Jadi, Anda mengambil Peko sehingga Anda bisa...",
  ui_story_31780401_104_dialog_content = "Aku tahu semua tentang bangsawan Lumopolis yang mengaku menyukai binatang buas.",
  ui_story_31780401_105_dialog_content = "Lagi pula, kami dulu berurusan dengan mereka sepanjang waktu.",
  ui_story_31780401_106_dialog_content = "Mereka membuang binatang buas mereka yang menakjubkan setiap kali mereka menjadi sedikit tidak nyaman bagi mereka.",
  ui_story_31780401_107_dialog_content = "Tidak mungkin aku bisa membiarkannya kembali ke kehidupan seperti itu.",
  ui_story_31780401_108_dialog_content = "Kau benar.",
  ui_story_31780401_109_dialog_content = "Anda menyadari bahwa saya dapat melaporkan Anda ke Balai Kehakiman Lumopolis atas apa yang telah Anda lakukan, bukan?",
  ui_story_31780401_110_dialog_content = "Meh, aku benar-benar tidak peduli. Saya bisa tidur dan menulis di mana saja.",
  ui_story_31780401_111_dialog_content = "Tetapi jika teman mulia Anda mengetahui bahwa Anda menggunakan \"milik pribadi\" mereka untuk mengadakan kompetisi tanpa izin mereka ...",
  ui_story_31780401_112_dialog_content = "dan bahwa Anda kehilangan satu, sementara yang lain dijinakkan ke standar sub-par...",
  ui_story_31780401_113_dialog_content = "Kalau begitu, saya khawatir persahabatan dan reputasi Anda mungkin dalam bahaya.",
  ui_story_31780401_114_dialog_content = "Apa yang kamu katakan?",
  ui_story_31780401_115_dialog_content = "Peko-peko!",
  ui_story_31780401_116_dialog_content = "peko?",
  ui_story_31780401_117_dialog_content = "Peko.",
  ui_story_31780401_118_dialog_content = "peko!",
  ui_story_31780401_119_dialog_content = "Peko-peko.",
  ui_story_31780401_120_dialog_content = "Peko! Peko-peko!",
  ui_story_31780401_121_dialog_content = "Wow! Vic bisa berbicara bahasa Peko!",
  ui_story_31780401_122_dialog_content = "Dan Peko ini tampak sangat bahagia—dia bahkan menghampirinya dan menggosok tangannya!",
  ui_story_31780401_123_dialog_content = "I-Ini...",
  ui_story_31780401_124_dialog_content = "Jika Anda bahkan tidak bisa mencapai sejauh ini dalam sepuluh hari, saya rasa Anda masih harus banyak belajar.",
  ui_story_31780401_125_dialog_content = "Lebih mudah untuk berkomunikasi dengan hewan yang luar biasa daripada dengan hewan biasa karena mereka memiliki pikirannya sendiri.",
  ui_story_31780401_126_dialog_content = "Sangat mudah untuk mendapatkan kepercayaan mereka selama Anda menguasai seni berkomunikasi dengan mereka.",
  ui_story_31780401_127_dialog_content = "...",
  ui_story_31780401_128_dialog_content = "Anak muda, siapa kamu?",
  ui_story_31780401_129_dialog_content = "Saya? Namanya Vic.",
  ui_story_31780401_130_dialog_content = "Vic? Mengapa itu terdengar begitu akrab?",
  ui_story_31780401_131_dialog_content = "Tunggu, jangan bilang kau...?",
  ui_story_31780401_132_dialog_content = "Apakah Anda penulis buku \"1.001 Makhluk Fantastis\"? Ahli ekstrozoologi terkenal itu?",
  ui_story_31780401_133_dialog_content = "Ya, ya, itu aku.",
  ui_story_31780401_134_dialog_content = "Saya tidak menyadari bahwa saya berada di hadapan seorang guru sejati.",
  ui_story_31780401_135_dialog_content = "Seseorang yang bisa berkomunikasi dengan binatang buas yang luar biasa di usia yang begitu muda!",
  ui_story_31780401_136_dialog_content = "Yah, jangan merasa terlalu buruk.",
  ui_story_31780401_137_dialog_content = "Anda tidak jauh lebih tua dari saya.",
  ui_story_31780401_138_dialog_content = "...",
  ui_story_31780401_139_dialog_content = "Tidak terlalu yakin dengan apa yang Anda bicarakan, tapi... pokoknya, saya akan memikirkan cara untuk mengatasi masalah Anda melepaskan salah satu kelinci.",
  ui_story_31780401_140_dialog_content = "Selama Anda bersedia mengajari saya cara berkomunikasi dengan binatang buas yang menakjubkan.",
  ui_story_31780401_141_dialog_content = "Bukan masalah.",
  ui_story_31780401_142_dialog_content = "Anda dapat menemukan saya di klinik hewan di Umbraton hampir setiap hari.",
  ui_story_31780401_143_dialog_content = "Maka itu kesepakatan. Aku akan datang mengunjungimu di masa depan.",
  ui_story_31780401_144_dialog_content = "Aku masih harus pergi ke Lumopolis hari ini, jadi aku akan pergi.",
  ui_story_31780401_145_dialog_content = "Wow, lelaki tua itu sangat dangkal. Sikapnya benar-benar berubah begitu dia tahu siapa kamu!",
  ui_story_31780401_146_dialog_content = "Apakah Anda tidak memiliki masalah dengan dia membawa Peko lain itu kembali ke bangsawan?",
  ui_story_31780401_147_dialog_content = "Mau bagaimana lagi? Peko tidak murah.",
  ui_story_31780401_148_dialog_content = "Saya sudah melepaskan satu. Secara teknis itu cukup bagi saya untuk berakhir di Penjara Lumopolis selama setahun.",
  ui_story_31780401_149_dialog_content = "Hmm... Poin bagus.",
  ui_story_31780401_150_dialog_content = "Tapi kenapa kamu menjinakkan Peko itu untuknya, Vic?",
  ui_story_31780401_151_dialog_content = "Hanya membayangkan dia mengambil pujian atas pekerjaanmu membuat darahku mendidih...",
  ui_story_31780401_152_dialog_content = "Saya tidak peduli tentang orang tua itu.",
  ui_story_31780401_153_dialog_content = "Tapi jika Peko itu menggigit seseorang lagi, itu pasti akan dijatuhkan.",
  ui_story_31780401_154_dialog_content = "Tidak dapat dihindari jika saya tidak ikut campur, mengingat bagaimana kelihatannya.",
  ui_story_31780401_155_dialog_content = "Oke!",
  ui_story_31780401_156_dialog_content = "Anda menjinakkan Peko untuk memastikannya bertahan.",
  ui_story_31780401_157_dialog_content = "Saya harus mengatakan, Vic, Anda benar-benar membuat saya terkesan hari ini!",
  ui_story_31780401_158_dialog_content = "Omong-omong, aku tidak pernah tahu kamu bekerja di klinik hewan.",
  ui_story_31780401_159_dialog_content = "Hah, terkadang kamu benar-benar naif.",
  ui_story_31780401_160_dialog_content = "Eh?",
  ui_story_31780401_161_dialog_content = "Itu hanya kebohongan kecil—aku tidak ingin melihat pria itu lagi.",
  ui_story_31780401_162_dialog_content = "Tanganku sudah penuh dengan Fia dan Shira. Saya tidak tahan untuk memiliki magang lain seperti dia menyeret saya ke bawah.",
  ui_story_31780401_163_dialog_content = "PlayerName, kamu masih terlalu muda untuk sepenuhnya memahami cara-cara dunia...",
  ui_story_31780401_164_dialog_content = "... Saya kira saya.",
  ui_story_31780601_1_dialog_content = "<color=#e8d9bb>Krucuuuuk...</color>",
  ui_story_31780601_2_dialog_content = "Hei, suara apa itu? Apakah kamu merasakan sesuatu dengan indera khususmu itu?",
  ui_story_31780601_3_dialog_content = "Itu suara perutku keroncongan!",
  ui_story_31780601_4_dialog_content = "Aku juga kelaparan... Kami sudah menghabiskan semua makanan kering yang kami bawa bersama kami.",
  ui_story_31780601_5_dialog_content = "Dan kamu masih lapar?! Aku tidak bisa percaya kamu menghabiskan semua ransum sendirian!",
  ui_story_31780601_6_dialog_content = "Hah? Dan kapan Anda mengklaim saya melakukannya? Hic—",
  ui_story_31780601_7_dialog_content = "Saat aku sibuk mencoba mendeteksi harta karun!",
  ui_story_31780601_8_dialog_content = "Heheh, jadi kamu melihatku, ya? Aneh... padahal aku menunggu sampai kamu membelakangi.",
  ui_story_31780601_9_dialog_content = "Apa kamu tahu betapa kerasnya suara kamu mengunyah?!",
  ui_story_31780601_10_dialog_content = "Nah, selama ini aku berusaha menjaga semangatmu, Nak. Sungguh melelahkan!",
  ui_story_31780601_11_dialog_content = "Hah? Saya belum mendengar satu kata pun motivasi darimu!",
  ui_story_31780601_12_dialog_content = "Aku telah mendukungmu... di hatiku.",
  ui_story_31780601_13_dialog_content = "... Jika aku bisa kembali ke masa lalu, tidak mungkin aku memilih pergi ke laut bersamamu, Vic.",
  ui_story_31780601_14_dialog_content = "<color=#e8d9bb>Beberapa jam sebelumnya...</color>",
  ui_story_31780601_15_dialog_content = "Oh, bukankah itu Vic dan Shira di depan sana? Sudah lama kita tidak berkumpul. Sepertinya aku harus pergi dan menyapa mereka.",
  ui_story_31780601_16_dialog_content = "—Aku sedang tidak begitu semangat.",
  ui_story_31780601_17_dialog_content = "Ini harta karun seumur hidup! Begitu kita berhasil mendapatkannya, semua orang akan mendapat bagian yang sama—dan itu termasuk kamu juga, nak!",
  ui_story_31780601_18_dialog_content = "Yah... semoga perjalananmu aman.",
  ui_story_31780601_19_dialog_content = "Kamu tidak peduli sama sekali dengan tuanmu? Coba bayangkan aku sendirian di lautan yang penuh bahaya itu—bahaya, ketakutan! Dan bagaimana jika ada monster laut menyerang? Aku membutuhkanmu di sana untuk membantuku mengatasi hal-hal seperti ini!",
  ui_story_31780601_20_dialog_content = "Tentu saja. Itu semakin menjadi alasan kamu harus pergi sendiri.",
  ui_story_31780601_21_dialog_content = "Kalian berdua memang memiliki hubungan yang aneh antara guru dan murid...",
  ui_story_31780601_22_dialog_content = "PlayerName! Luar biasa! Ayo bersama-sama menjelajahi lautan lepas!",
  ui_story_31780601_23_dialog_content = "Pukul apa sekarang?",
  ui_story_31780601_24_dialog_content = "Laut lepas, nak! Kamu pasti pernah dengar rumor-nya? Harta karun Raja Bajak Laut yang hilang telah muncul kembali!",
  ui_story_31780601_25_dialog_content = "Raja Bajak Laut yang perkasa mengjarah banyak harta karun pada masanya dan menyembunyikannya di lokasi misterius yang hanya bisa ditemukan oleh penjelajah paling berani dan cerdas.",
  ui_story_31780601_26_dialog_content = "Ini terdengar seperti cerita dari salah satu buku bergambar Fia...",
  ui_story_31780601_27_dialog_content = "Sumber yang dapat diandalkan memberitahu saya bahwa harta karun emas ini terletak jauh di bawah gelombang laut!",
  ui_story_31780601_28_dialog_content = "Aku tidak begitu yakin tentang itu, maksudku, aku tahu definisi \"andal\" menurutmu...",
  ui_story_31780601_29_dialog_content = "Saya hanya seorang pria tua yang kesepian berusaha membesarkan dua murid yang menggemaskan sendirian—kaki saya beruban, telinga saya keriput, mata saya tua dan bengkok.",
  ui_story_31780601_30_dialog_content = "Kamu selalu malas! Fia dan aku yang selalu menjagamu!",
  ui_story_31780601_31_dialog_content = "Ahem, baiklah, sekarang setelah saya akhirnya mengetahui informasi tentang harta karun, saya siap menghadapi serangkaian perangkap bajak laut jika harus, semua demi mendapatkan uang susu untuk anak kesayangan saya, Fia!",
  ui_story_31780601_32_dialog_content = "Fia bukan lagi bayi kecil yang minum susu.",
  ui_story_31780601_33_dialog_content = "PlayerName, tentu kamu bisa mengerti, harus merawat Colossus sebesar itu dan semuanya. Rasanya seperti ada lubang di kantongmu, dan aku punya dua lubang!",
  ui_story_31780601_34_dialog_content = "Nah, sekarang Anda menyebutkannya... Sebenarnya, saya ingin memperindah Colossus baru-baru ini, tetapi saya tidak bisa mengumpulkan dana untuk mewujudkannya...",
  ui_story_31780601_35_dialog_content = "Tapi dengan kemampuan psikis unikmu, kita pasti akan menemukan harta karun itu dalam waktu singkat! Harta karun emas, kami datang!",
  ui_story_31780601_36_option_content = "Tunjukkan pantatnya!",
  ui_story_31780601_37_dialog_content = "Shira, kamu tunggu di sini—kami akan kembali dengan barang-barangnya sebelum kamu menyadarinya!",
  ui_story_31780601_38_option_content = "Bisakah aku menyimpan semua harta karun untuk diriku sendiri?",
  ui_story_31780601_39_dialog_content = "Persis seperti yang kuduga dari seorang Caelestite—kau berhasil mencium aroma tulus dari niat hatiku yang paling jujur.",
  ui_story_31780601_40_dialog_content = "...",
  ui_story_31780601_41_dialog_content = "Menguap... Pastikan kau kembali dengan selamat.",
  ui_story_31780601_42_dialog_content = "Menurut sumber saya, harta karun seharusnya berada di area laut ini. Apakah kamu benar-benar tidak merasakan apa-apa di sini sama sekali?",
  ui_story_31780601_43_dialog_content = "Tidak, tidak ada apa-apa. Mungkin area ini terlalu besar atau dalam... mungkin kemampuan psikisku terlalu lemah, atau mungkin... harta karun itu memang tidak ada.",
  ui_story_31780601_44_dialog_content = "Aku lapar... dan aku sangat haus di sini... Ayo kita kembali saja...",
  ui_story_31780601_45_dialog_content = "Lihat! Ada cahaya yang bersinar di dalam air!",
  ui_story_31780601_46_dialog_content = "Cahaya mengalir ke arah kita. Apakah itu... ubur-ubur?",
  ui_story_31780601_47_dialog_content = "Aku tidak menyangka kita akan menemui jenis ubur-ubur seperti ini di sini.",
  ui_story_31780601_48_dialog_content = "Apakah ini spesies langka? Cahaya yang mereka pancarkan terasa sangat berbeda dari apa pun yang pernah saya lihat sebelumnya.",
  ui_story_31780601_49_dialog_content = "Memang, mereka bukan ubur-ubur biasa. Bahkan, makhluk ajaib ini mungkin bisa membawa kita menemukan harta karun!",
  ui_story_31780601_50_dialog_content = "Lihat, seakan-akan mereka mengeluarkan kepala dari air untuk menyapa.",
  ui_story_31780601_51_dialog_content = "Hei, ubur-ubur kecil yang lucu! Bagaimana kabarmu hari ini?",
  ui_story_31780601_52_dialog_content = "Hati-hati! Ubur-ubur ini berbisa! Cukup satu sentuhan dan—",
  ui_story_31780601_53_dialog_content = "Empuk sekali... begitu halus... ah... urgh...",
  ui_story_31780601_54_dialog_content = "Hei, kenapa kamu menyentuhnya?!",
  ui_story_31780601_55_dialog_content = "...",
  ui_story_31780601_56_dialog_content = "...",
  ui_story_31780601_57_dialog_content = "PlayerName... Bangun, PlayerName.",
  ui_story_31780601_58_dialog_content = "Urgh... Apa yang terjadi?",
  ui_story_31780601_59_dialog_content = "Kamu pingsan karena sengatan ubur-ubur, lalu sekolah ubur-ubur menyeret rakit kita ke sini.",
  ui_story_31780601_60_dialog_content = "Di sini sangat gelap. Di mana kita?",
  ui_story_31780601_61_dialog_content = "Sepertinya ini adalah gua rahasia semacam itu. Saya percaya ini mungkin tempat harta karun itu disembunyikan!",
  ui_story_31780601_62_dialog_content = "Aku tidak melihat harta karun di sekitar sini, tapi aku bisa merasakan kehadiran yang berbahaya di sekeliling kita.",
  ui_story_31780601_63_dialog_content = "Selama aku di sini, kamu bisa tertawa menghadapi bahaya.",
  ui_story_31780601_64_dialog_content = "Kalau memang tak ada yang perlu ditakuti, kenapa kamu bersembunyi di belakangku?",
  ui_story_31780601_65_dialog_content = "Yah, itu karena memang tidak begitu aman di sini, bukan sekarang?",
  ui_story_31780601_66_dialog_content = "...",
  ui_story_31780601_67_dialog_content = "Heheh, hanya bercanda. Anda akan aman—aman di tangan seorang ahli ekstrozoologi yang pemberani dan luar biasa!",
  ui_story_31780601_68_dialog_content = "Yang perlu saya lakukan hanyalah memanggil binatang ajaib saya, dan apapun musuh jahat yang kita hadapi, kita tidak perlu takut, bahkan tidak untuk satu detik sekalipun!",
  ui_story_31780601_69_dialog_content = "Di mana teman-teman binatang ajaibmu? Mengapa belum memanggil mereka?",
  ui_story_31780601_70_dialog_content = "Ah, ya, sinyal di sini kurang bagus...",
  ui_story_31780601_71_dialog_content = "Kree—Kree—!",
  ui_story_31780601_72_dialog_content = "Ah! Suara apa itu? Seluruh gua berguncang!",
  ui_story_31780601_73_dialog_content = "Aku punya firasat buruk tentang ini. Pasti ada monster mengerikan yang menunggu kita di depan!",
  ui_story_31780601_74_dialog_content = "Saya tidak perlu kemampuan psikis untuk tahu bahwa kita harus segera keluar dari sini!",
  ui_story_31780601_75_dialog_content = "Tunggu sebentar. Monster seperti itu tidak akan muncul tanpa alasan! Kita pasti semakin dekat dengan harta karun!",
  ui_story_31780601_76_dialog_content = "Kamu sungguh masih memikirkan harta karun saat nyawamu sedang terancam?",
  ui_story_31780601_77_dialog_content = "Seperti yang sudah kukatakan, kamu tidak perlu khawatir tentang apapun selama aku ada di sekitarmu.",
  ui_story_31780601_78_dialog_content = "Burung Hantu Lutumi!",
  ui_story_31780601_79_dialog_content = "Hoot—hoot-hoot!",
  ui_story_31780601_80_dialog_content = "Bica!",
  ui_story_31780601_81_dialog_content = "Hai-hai!",
  ui_story_31780601_82_dialog_content = "Bola Bulu Kecil!",
  ui_story_31780601_83_dialog_content = "Chirrrr—!",
  ui_story_31780601_84_dialog_content = "Berubah!",
  ui_story_31780601_85_dialog_content = "Chirrrr—!",
  ui_story_31780601_86_dialog_content = "Woah... Mereka benar-benar datang!",
  ui_story_31780601_87_dialog_content = "Tetap di belakangku dan jangan takut—aku akan melindungimu!",
  ui_story_31780601_88_dialog_content = "(Aneh. Kenapa dia tiba-tiba terlihat begitu intens?)",
  ui_story_31780601_89_dialog_content = "Terus maju—harta karun ada tepat di depan!",
  ui_story_31780601_90_dialog_content = "Hei, apa itu benda mengkilap di tanah?",
  ui_story_31780601_91_dialog_content = "Emas! Ini emas!",
  ui_story_31780601_92_dialog_content = "Lautan cahaya emas yang sangat besar bersinar di depan... Kamu melihatnya?!",
  ui_story_31780601_93_dialog_content = "Ini harta karunnya! Ayo kita ambil!",
  ui_story_31780601_94_dialog_content = "Kree! Kree—!",
  ui_story_31780601_95_dialog_content = "Ahhhh!!!",
  ui_story_31780601_96_dialog_content = "Ouroboros?!",
  ui_story_31780601_97_dialog_content = "Bukankah itu terbang bersama Eulogoz? Apa yang sedang dilakukan di sini?",
  ui_story_31780601_98_dialog_content = "Kree, kree—kree!",
  ui_story_31780601_99_dialog_content = "Woah!",
  ui_story_31780601_100_dialog_content = "Awas!",
  ui_story_31780601_101_dialog_content = "Ouroboros mengambil koin emas saya!",
  ui_story_31780601_102_dialog_content = "Ini menjaga harta karun ini.",
  ui_story_31780601_103_dialog_content = "Aneh, saya belum pernah mendengar tentang Ouroboros yang memiliki kegemaran mengumpulkan emas.",
  ui_story_31780601_104_dialog_content = "Sepertinya kita harus mengalahkannya sebelum kita bisa mengambil harta karun.",
  ui_story_31780601_105_dialog_content = "Mengalahkan Ouroboros? Bagaimana kita akan melakukannya?",
  ui_story_31780601_106_dialog_content = "Tidak perlu banyak bicara, Ouroboros telah sedikit tenang... Kita hanya perlu menangkap momen yang tepat...",
  ui_story_31780601_107_dialog_content = "Jangan berpikir untuk menyakitinya. Saya ingat Ouroboros adalah makhluk yang lembut dan baik hati. Saya tidak pikir itu akan menyerang kita.",
  ui_story_31780601_108_dialog_content = "Mungkin harta karun telah merusak pikirannya dan berubah menjadi iblis pencuri harta yang serakah...",
  ui_story_31780601_109_dialog_content = "Kree, Kree!",
  ui_story_31780601_110_dialog_content = "Lutumi Owl, Bica, Bola Bulu Besar—kalahkan!",
  ui_story_31780601_111_dialog_content = "...",
  ui_story_31780601_112_dialog_content = "...",
  ui_story_31780601_113_dialog_content = "...",
  ui_story_31780601_114_dialog_content = "Hei! Jangan berani-berani!",
  ui_story_31780601_115_dialog_content = "Kree, kree—kree!",
  ui_story_31780601_116_dialog_content = "Hei, tenang, tenang... Kami tidak di sini untuk mencuri emas Anda, teman, kami hanya di sini untuk melihat-lihat... Hei, mungkin kita bahkan bisa menjadi sahabat terbaik? Bagaimana menurutmu?",
  ui_story_31780601_117_dialog_content = "Kree, kree?",
  ui_story_31780601_118_dialog_content = "Percayalah padaku! Saya adalah ahli ekstrozoologi terkemuka di seluruh benua ini—berkomunikasi dengan Ouroboros adalah salah satu keahlian beragam yang saya miliki.",
  ui_story_31780601_119_dialog_content = "Kree—",
  ui_story_31780601_120_dialog_content = "Ayo, biarkan aku memelukmu.",
  ui_story_31780601_121_dialog_content = "Vic, apa yang menurutmu sedang kamu lakukan?",
  ui_story_31780601_122_dialog_content = "Perhatikan baik-baik! Saya akan menggunakan kemampuan Ouroboros Charmer rahasia saya—",
  ui_story_31780601_123_dialog_content = "Gerakan pertama adalah Sikap Penjepit Wajah, di mana seseorang menggunakan kedua tangan untuk membelai pipi, membuatnya hangat seketika!",
  ui_story_31780601_124_dialog_content = "Gerakan kedua adalah Tiptoe Saunter, di mana kamu berdiri di ujung jari kaki dan berjalan bolak-balik di punggungnya, membuat Ouroboros yang paling waspada sekalipun menjadi rileks!",
  ui_story_31780601_125_dialog_content = "Jarang sekali melihatmu menganggap sesuatu ini serius. Kurasa saat harta karun terlibat, kamu memang punya sisi yang dapat diandalkan.",
  ui_story_31780601_126_dialog_content = "Kree, kree, kree!",
  ui_story_31780601_127_dialog_content = "Lihat bagaimana mata Ouroboros menyempit? Itu berarti ia mulai merasa sangat nyaman.",
  ui_story_31780601_128_dialog_content = "Kree!",
  ui_story_31780601_129_dialog_content = "Hei?! Bagaimana mungkin dia bisa berubah menjadi telur?",
  ui_story_31780601_130_dialog_content = "Mungkin dia merasa sangat nyaman sehingga tertidur?",
  ui_story_31780601_131_dialog_content = "Jadi... semua emas ini milik kita sekarang?",
  ui_story_31780601_132_dialog_content = "Benar, kamu bisa mengemasnya dan membawanya keluar dari sini.",
  ui_story_31780601_133_dialog_content = "Wahahahaha! Akhirnya aku punya cukup uang untuk memperbaiki Colossus! Ini cukup untuk melapisi seluruh interior Soroz dengan emas!",
  ui_story_31780601_134_dialog_content = "Oh, ya ampun. Aku harus mulai renovasi dari mana ya? Jembatan? Generator? Atau mungkin aku harus membangun perluasan di kamarku?",
  ui_story_31780601_135_dialog_content = "Kamu tahu aku bukan tipe orang yang suka boros, tapi tidak ada salahnya membuat kamarku sedikit lebih nyaman, bukan?",
  ui_story_31780601_136_dialog_content = "Bersihkan mulutmu, kamu ngiler.",
  ui_story_31780601_137_dialog_content = "Hehehe, maaf, sepertinya aku jadi agak terlalu bersemangat!",
  ui_story_31780601_138_dialog_content = "Hah? Kenapa kamu tidak mengambil emas itu? Kamu hanya berdiri di sana menatapnya seperti tidak menginginkannya.",
  ui_story_31780601_139_dialog_content = "Kurasa sudah saatnya kau bangun sekarang.",
  ui_story_31780601_140_dialog_content = "Hah? Apa yang kau bicarakan?",
  ui_story_31780601_141_dialog_content = "Aku bilang... ini semua tidak nyata... ini semua hanyalah ilusi...",
  ui_story_31780601_142_dialog_content = "Aduh... Kepalaku sakit...",
  ui_story_31780601_143_dialog_content = "Pfffff! Kenapa ada rumput semua di mulutku ini?!",
  ui_story_31780601_144_dialog_content = "Itulah tanaman yang menyelamatkan hidupmu, Nak! Lap mulutmu sekarang, obatnya keluar semua.",
  ui_story_31780601_145_dialog_content = "Urgh... Aku... Di mana ini?",
  ui_story_31780601_146_dialog_content = "Kamu berada di rakit, tentu saja! Di mana lagi kamu bisa berada?",
  ui_story_31780601_147_dialog_content = "Rakit? Rakit apa?",
  ui_story_31780601_148_dialog_content = "Benda kayu yang kita tumpangi mengapung sekarang ini! Apakah kamu kehilangan ingatanmu?",
  ui_story_31780601_149_dialog_content = "T-Tidak... Aku ingat... Aku ingat kita dibawa ke sebuah gua oleh ubur-ubur...",
  ui_story_31780601_150_dialog_content = "Oh, ubur-ubur masih ada di sini.",
  ui_story_31780601_151_dialog_content = "Gua yang Anda sebutkan ini penuh dengan emas dan dijaga oleh Ouroboros, benar?",
  ui_story_31780601_152_dialog_content = "Ya! Kamu juga ada di sana!",
  ui_story_31780601_153_dialog_content = "Aku belum pernah ke tempat itu, tapi kamu terus berteriak—",
  ui_story_31780601_154_dialog_content = "Kamu bilang kamu akan mengambil semua harta dan melapisi seluruh interior Soroz dengan emas. Dan sesuatu tentang membangun perluasan di kamarmu. Memang terdengar seperti mimpi yang indah.",
  ui_story_31780601_155_dialog_content = "Mimpi? Tidak mungkin itu semua hanya mimpi!",
  ui_story_31780601_156_dialog_content = "Semua ini karena ubur-ubur—Ubur-ubur Dreamweaver. Ia memiliki kemampuan untuk membaca pikiran dan emosi siapa pun yang menyentuhnya.",
  ui_story_31780601_157_dialog_content = "Mereka memiliki kekuatan untuk menciptakan visi paling sempurna atau paling mengerikan dalam pikiran orang yang terpengaruh, berdasarkan ketakutan dan keinginan terdalam mereka.",
  ui_story_31780601_158_dialog_content = "Jadi... Jadi keinginan terdalamku adalah... untuk emas?",
  ui_story_31780601_159_dialog_content = "Benar! Sebagai Caelestite terakhir, yang bisa kamu pikirkan hanyalah emas, tidak ada ambisi besar atau cita-cita mulia yang terlihat!",
  ui_story_31780601_160_dialog_content = "Anu... Yah... Aku hanya...",
  ui_story_31780601_161_dialog_content = "Heehee! Hanya kita berdua di sini, kamu tidak perlu menjelaskan dirimu padaku.",
  ui_story_31780601_162_dialog_content = "Aku benar-benar mengerti kamu. Jika aku menyentuh benda itu, mungkin aku akan memiliki mimpi yang sama persis!",
  ui_story_31780601_163_dialog_content = "Itu bukan masalahnya. Saya bukan orang yang serakah. Mimpi itu pasti semacam gangguan otak!",
  ui_story_31780601_164_dialog_content = "Mengapa lagi kau mau mempertaruhkan nyawa dan anggota tubuh untuk menemani aku di rakit yang goyah ini?",
  ui_story_31780601_165_dialog_content = "Aku khawatir mungkin terlalu berbahaya bagi kamu untuk berlayar sendirian!",
  ui_story_31780601_166_dialog_content = "Jadi, apakah kamu masih akan ikut denganku jika tidak ada harta karun yang bisa didapatkan?",
  ui_story_31780601_167_option_content = "Kurasa tidak.",
  ui_story_31780601_168_dialog_content = "(Hela) Jadi harta karun Raja Bajak Laut memang hanya legenda belaka... Yah, ini adalah terakhir kalinya aku percaya semua yang kubaca di buku bergambar Fia!",
  ui_story_31780601_169_dialog_content = "Kamu dapat semua ini dari buku cerita anak-anak?!",
  ui_story_31780601_170_dialog_content = "Ngomong-ngomong, saya sama sekali tidak tahu arah mana kita terapung sekarang ini.",
  ui_story_31780601_171_dialog_content = "Aku melakukan segala yang bisa untuk menyelamatkanmu, jadi wajar saja aku kehilangan jejak arah arus yang membawa kita.",
  ui_story_31780601_172_dialog_content = "Kita perlu memikirkan cara untuk pulang ke rumah.",
  ui_story_31780601_173_dialog_content = "Ada ide?",
  ui_story_31780601_174_dialog_content = "Nah, selalu ada metode paling primitif namun paling efektif—",
  ui_story_31780601_175_dialog_content = "Tolong!!!"
}
return config
